def esc(s):return html.escape(str(s)).replace('\n','<br/>')
def P(s):return Paragraph(esc(s),S['BodyA'])
def small(s):return Paragraph(esc(s),S['SmallA'])
def H(s):return Paragraph(esc(s),S['SubA'])
def T(rows,widths):
 t=Table([[Paragraph(esc(x),S['CellA']) for x in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e2ebf1')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f6f8fa')]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#a7bac7'))]))
 return t
class Field(Flowable):
 def __init__(self,key,label,height=27):
  Flowable.__init__(self);self.key=key;self.label=label;self.box=height;self.height=height+23;self.width=475
 def draw(self):
  c=self.canv;c.setFont('Times-Bold',10);c.setFillColor(colors.HexColor('#173b55'));c.drawString(0,self.box+7,self.label);x,y=c.absolutePosition(0,0)
  c.acroForm.textfield(name=self.key,tooltip=self.label,x=x,y=y,width=475,height=self.box,fontName='Times-Roman',fontSize=11,fillColor=colors.HexColor('#fffdf5'),borderColor=colors.HexColor('#a9b8c3'),borderWidth=.6,forceBorder=True,fieldFlags='multiline' if self.box>30 else '',maxlen=5000)
class Calendar(Flowable):
 def __init__(self,rows):
  Flowable.__init__(self);self.rows=rows;self.width=475;self.height=30+len(rows)*30
 def draw(self):
  c=self.canv;y=self.height-25;c.setFillColor(colors.HexColor('#e2ebf1'));c.rect(0,y,475,25,fill=1,stroke=0);c.setFillColor(colors.HexColor('#173b55'));c.setFont('Times-Bold',9)
  for x,label in [(6,'Card / activity'),(240,'Start date'),(355,'Due date')]:c.drawString(x,y+9,label)
  for i,(card,label) in enumerate(self.rows):
   y-=30;c.setFillColor(colors.HexColor('#f6f8fa') if i%2==0 else colors.white);c.rect(0,y,475,30,fill=1,stroke=0);c.setFont('Times-Roman',9);c.setFillColor(colors.black);c.drawString(6,y+11,f'{card:02d}  '+label)
   for x,kind in [(240,'start'),(355,'due')]:
    ax,ay=c.absolutePosition(x,y+4)
    c.acroForm.textfield(name=f'card_{card:02d}_{kind}',tooltip=f'Card {card} {kind} date YYYY-MM-DD',x=ax,y=ay,width=108,height=22,fontName='Times-Roman',fontSize=10,fillColor=colors.HexColor('#fffdf5'),borderColor=colors.HexColor('#a9b8c3'),borderWidth=.5,forceBorder=True,maxlen=10)
story=[]
def section(title):story.extend([PageBreak(),Paragraph(esc(title),S['SectionA'])])

story += [Spacer(1,14),small('BUKIDNON STATE UNIVERSITY\nCollege of Technologies\nInformation Technology Department'),Spacer(1,30),Paragraph('Academic Early Warning System',S['TitleA']),Paragraph('Test Plan and Schedule',S['SectionA']),P('IT143 CO3 Major Assessment\nQuality Assurance Project Management Framework'),Spacer(1,12),T([['Document control','Details'],['Identifier / version','AEWS-QA-TP-001 / 2.0'],['Preparation date','7 November 2026'],['Requirements reference','AEWS-QA-RR-001, Requirements Review Report, version 2.0'],['Associated Trello task','Card 2 - Prepare AEWS Test Plan and Schedule'],['Status','Proposed plan; team assignments, calendar and approval pending']],[145,330]),Spacer(1,13),H('Plan overview'),P('This plan defines the scope, methods, responsibilities, resources, evidence and schedule for quality assurance of the Academic Early Warning System (AEWS). It aligns seventeen requirement groups with forty prepared test cases and adds targeted scenarios for the seven findings in the requirements review.'),P('Execution follows a proposed seventeen-working-day schedule with explicit dependencies, initial testing, defect resolution, regression and final review. Actual calendar dates and member assignments are recorded in editable fields. No testing, defect resolution or approval is represented as completed by this planning document.'),small('The plan supports the assessment guidelines and rubric [1-2]. Its proposed quality targets and internal schedule are not instructor-mandated deadlines.')]

section('1. Objectives and Test Scope')
story += [H('1.1 Objectives'),P('Verify that AEWS preserves academic-data accuracy, enforces identity and record permissions, supports a traceable early-intervention workflow and produces consistent reports. Detect defects before the Capstone evaluation, provide reproducible evidence, and support an explicit readiness decision based on observed results.'),H('1.2 In-scope requirements'),T([['Requirement coverage','Verification focus','Main cases'],['R01-R03: identity and access','Registration, approval, session/recovery, role and ownership boundaries','TC-01 to TC-08'],['R04-R05: classes and imports','Class lifecycle; supported files; identity matching; invalid and duplicate input','TC-09 to TC-15'],['R06-R07: academic accuracy','Term/component separation, grade validity, attendance calculation and missing data','TC-16 to TC-18'],['R08-R09: referrals/assessment','Referral boundaries, student linkage, form validation and invitation lifecycle','TC-19 to TC-24'],['R10-R11: prediction/routing','Input sufficiency, provenance, output meaning and controlled communications','TC-25 to TC-30'],['R12-R13: student/admin','Own-student profile/dashboard; account/form changes and audit behavior','TC-31 to TC-34'],['R14: reports','Role-scoped totals, filters, exported content and layout','TC-35 to TC-36'],['R15-R16: quality attributes','Task usability, keyboard/narrow viewports and measured response times','TC-37 to TC-39'],['R17: integration','Complete intervention workflow and fix-related regression','TC-40 and related cases']],[145,245,85]),H('1.3 Exclusions and boundaries'),P('Exclude unapproved production changes, university-wide load certification, unrestricted penetration testing and claims of real-world student-outcome effectiveness. The planned security checks use controlled test accounts and isolated data. Model accuracy is assessed only through documented evaluation evidence; successful inference does not establish predictive accuracy.'),P('The approved specification governs expected results. The requirements review [3] identifies source observations and proposed requirements; unresolved policy decisions must be clarified before affected tests receive a pass/fail outcome.')]

section('2. Test Strategy and Execution Method')
story += [H('2.1 Risk-led sequence'),P('Begin with baseline review and environment readiness, followed by account/ownership isolation and import accuracy. Establish trustworthy academic fixtures before validating referrals, assessments, prediction and intervention. Exercise reporting and quality attributes on a stable build. Reserve explicit time for fixes, retesting and integration regression.'),T([['Method','Application and evidence'],['Static review','Resolve requirement ambiguity, review access/data contracts and confirm expected results before execution. Link decisions to R01-R17 and findings F01-F07.'],['Functional and integration','Test permitted role workflows through the interface and corresponding API. Record expected/actual behavior and persisted state where relevant.'],['Boundary and negative','Use valid/invalid credentials, referral limits, zero/missing values, invalid file types/sizes, duplicates, expired invitations and out-of-scope record IDs.'],['Independent reconciliation','Compare uploaded identities, grades, attendance, totals and export rows with independently prepared expected values.'],['Automated checks','Run existing backend/frontend suites and production build checks in the configured test environment. Retain logs and build identity; automation complements manual business-rule tests.'],['Retest and regression','Repeat original failed steps on the fixed build, verify boundary variants and rerun affected downstream functions before closing a defect.']],[120,355]),H('2.2 Execution record'),P('For each scenario, record the requirement/case ID, preconditions, exact input, build, environment, tester, date, expected result, actual result, status, sanitized evidence and linked defect. The case workbook supplies forty grouped procedures [4]. Give independent variants unique execution suffixes, such as TC-19-A and TC-19-B, rather than combining conflicting outcomes into one result.'),H('2.3 Status definitions'),P('Not run: execution has not occurred. Pass: observed outcome meets every applicable expected condition. Fail: an observed outcome differs from the approved expectation. Blocked: a prerequisite, environment condition or unresolved requirement prevents valid execution. A skipped or blocked case is never counted as a pass.')]

section('3. Targeted Security, Data and Model Checks')
story += [P('The requirements review identifies seven open findings [3]. The following supplemental scenarios extend the existing cases; they are planned checks, not executed findings or confirmed deployment behavior.'),T([['Review finding','Required scenario / expected verification'],['F01: trusted identity','Extend TC-06/07 with missing, invalid and expired tokens and untrusted user/role headers. Client-declared identifiers must not grant protected authority.'],['F02: student ownership','Extend TC-08/31/32 with no-session requests and another synthetic student identifier. Private reads and updates require approved identity and scope.'],['F03: prerequisites','Extend TC-25/26/28 for each missing source at each prediction entry point. Enforce the approved workflow-specific matrix; preserve valid zero and false/no values.'],['F04: grade domain','Extend TC-17/19/25 with zero, missing, negative, non-finite and above-range grades through import/update/inference paths. Apply the approved grade-domain policy.'],['F05: output semantics','Extend TC-27/35 to distinguish predicted risk, intervention-cause labels, probability scale and model/fallback source across API, interface and reports.'],['F06: quality targets','Approve workload, usability tasks and model/performance criteria before TC-27/37/38/39 is assessed for acceptance.'],['F07: lifecycle policies','Extend TC-10/13/24/34 for partial imports, duplicates, invitation expiry/reuse and existing invitations after form edits.']],[120,355]),H('3.1 AEWS-specific data distinctions'),P('Test the observed whole-midterm automatic referral interval of 2.50 through 5.00 inclusively only after confirming it against the approved academic policy. Test below the threshold and invalid above-range input. Do not equate a referral event with a predicted High Risk result. Attendance 0% is a valid observation; a missing attendance source is different.'),H('3.2 Model evaluation protocol'),P('Record artifact/profile/version, feature order, dataset origin and evaluation run. Examine train/test separation, student/duplicate leakage and outcome leakage. Report held-out sample counts, class distribution, confusion matrix, High Risk recall, precision and F1 with accuracy. Review fallback behavior separately. Record limitations of synthetic data and do not present historical stored metrics as newly reproduced results [6].')]

section('4. Test Environment, Data and Resources')
story += [H('4.1 Environment baseline'),P('Use a separate test database, controlled accounts and a fixed source/build version. Record React frontend and FastAPI service versions, browser/OS, database configuration and model artifact. Secrets are stored privately and are not entered in public attachments. Reset state between destructive/lifecycle variants to avoid test-order dependence [5-6].'),Field('build_environment','Source/build, frontend/API test locations and database alias',42),Field('browser_resources','Browser/OS, device/viewport and performance resources',36),Field('model_email','Model/profile/version and intercepted or controlled email setup',36),H('4.2 Synthetic accounts and fixtures'),P('Prepare two instructors with separate classes, an administrator, appropriate AMU staff and two student identities for cross-owner tests. Use genuine test-role assignments, not credentials copied from production. Intercept or disable external email for file-upload/referral scenarios.'),T([['Card 5 fixture','Purpose / expected values'],['Synthetic_Classlist.xlsx','Five invented student IDs and names using example.com addresses; load first into an isolated class.'],['Synthetic_Gradesheet.xlsx','Matching IDs; MTG values 2.25, 2.49, 2.50, 3.00 and 5.00. Load after roster preparation.'],['Synthetic_Attendance.xlsx','Five marked sessions; expected attendance 100%, 80%, 60%, 0% and 100%.'],['Negative fixtures','Duplicate classlist and unsupported text file. Add malformed, empty, mismatched and size-boundary fixtures for relevant cases.']],[175,300]),H('4.3 Preparation and cleanup'),P('Confirm fixture parsing in the current build; reconcile rows before using them as downstream inputs. For reports use known-count data; performance tests require a separately prepared 100-student synthetic class. Record reset/cleanup actions and retain only sanitized evidence needed for traceability.'),Field('environment_ready','Readiness check / environment owner / date / outstanding dependencies',40)]

section('5. Responsibilities and Coordination')
story += [P('Assign actual names to the functions below before scheduling execution. Roles may be combined in a four- or five-member group. A person may develop and test different modules, but another member should review their own fix evidence where practical.'),T([['Responsibility','Accountability'],['QA coordinator','Maintains plan, dependencies, milestones, triage, reporting and final review coordination.'],['Accounts/access tester','Covers authentication, role/ownership isolation, student portal and administrative state changes.'],['Academic-data tester','Covers classes, imports, grade/attendance reconciliation and data fixtures.'],['AMU/model tester','Covers referrals, assessments, prerequisite rules, prediction provenance and support routing.'],['Reports/quality tester','Covers dashboard/export reconciliation, usability, response-time measurement and integration regression.'],['Responsible developer','Investigates assigned defects, supplies fix/build reference and communicates impact; tester verifies closure.']],[145,330]),H('5.1 Actual assignments'),Field('qa_lead','QA coordinator / plan reviewer'),Field('access_tester','Accounts/access tester and reviewer'),Field('data_tester','Academic-data tester and reviewer'),Field('amu_tester','AMU/model tester and reviewer'),Field('quality_tester','Reports/quality tester and reviewer; shared assignment if needed'),H('5.2 Working practice'),P('Review active tasks and blockers each working day. Log decisions and progress on the appropriate Trello card. Triage critical/high issues promptly and revise the schedule when a prerequisite is delayed. The coordinator tracks due dates; every member maintains their assigned evidence and comments.')]

